"""Writes gate/testdata/isotonic_fixture.json: sklearn IsotonicRegression(out_of_bounds="clip", y_min=0, y_max=1)
fitted on seeded synthetic answers (ties included) and tabulated on np.linspace(0, 1, 101), the computation of
`gate fit-calibration` (mergeone/gate/cli.py). gate/internal/engine checks IsotonicFit against it.

    python3 gate/testdata/gen_isotonic_fixture.py
"""
import json
from pathlib import Path

import numpy as np
from sklearn.isotonic import IsotonicRegression

cases = []
for seed, n, digits in [(1, 400, 2), (2, 1000, 3), (3, 250, 1)]:
    rng = np.random.default_rng(seed)
    x = np.round(rng.beta(2, 3, n), digits)
    y = (rng.random(n) < 0.15 + 0.6 * x).astype(int)
    iso = IsotonicRegression(out_of_bounds="clip", y_min=0, y_max=1).fit(x, y)
    xs = np.linspace(0, 1, 101)
    cases.append({"seed": seed, "x": x.tolist(), "y": y.tolist(), "grid_y": iso.predict(xs).tolist()})
out = {"source": "sklearn " + __import__("sklearn").__version__ + " IsotonicRegression(out_of_bounds='clip', y_min=0, y_max=1); "
                  "generated by gate/testdata/gen_isotonic_fixture.py", "cases": cases}
Path(__file__).with_name("isotonic_fixture.json").write_text(json.dumps(out) + "\n")
print("wrote", len(cases), "cases")
